"""SYNTHETIC fixture data engineered to reproduce six qualitative mobility
scenarios of a real `presence_fixes` corpus. The data is synthetic and
programmatically generated so that no real person's location history lives in
the repo; `tests/unit/test_mobility_scenarios.py` consumes it.

Every row below is generated by `_dwell_track` (a small, seeded,
deterministic generator — `random.Random(<int>)`, never the unseeded
module-level `random` or a wall-clock seed) from a handful of parameters
(person_id, calendar span, local-HKT hour window, site coordinates,
fix cadence). No literal fix tuple is hand-typed; only the generator
parameters below are. Coordinates are fictional points inside the
Hong Kong bounding box (the algorithm is Asia/Hong_Kong-timezone-aware, so
staying in-region keeps the local-clock night/work windows meaningful) —
none of them match a real cell.

Six scenarios, five synthetic `person_id`s (one split across a rename):

  synthetic_worker_a     -- clean office worker: 09:00-18:00 weekdays,
                             zero night dwell -> `work`.
  synthetic_wfh_b        -- works from the same place she sleeps: dwell
                             spans both the night AND working-window terms
                             at ONE location, `night_share` landing just
                             under `_HOME_NIGHT_SHARE_MIN` (0.3) -- see the
                             near-miss note below. Stays `xfail`.
  synthetic_home_only_c  -- a real home cluster plus a second, minor
                             location whose total dwell (3h) never clears
                             `_MIN_WORK_DWELL_MS` (8h) -> no `work` place.
  synthetic_renamed_before / synthetic_renamed_after
                          -- one physical desk, two `person_id`s (a
                             simulated identity rename mid-tenure).
                             Neither half alone reaches 3 distinct
                             stays (below `cluster_places`' `min_samples`),
                             so segmenting them separately yields NO
                             cluster at all for either half; merged (the
                             production `subject_id` resolution's job) they
                             form one clean 4-weekday `work` cluster.
  synthetic_ambiguous_e  -- the fail-closed proof case: one cell carrying
                             substantial dwell in BOTH the night AND
                             weekday working-window terms -> `unlabeled`,
                             never a guess either way.

**The `synthetic_wfh_b` vs `synthetic_ambiguous_e` near-miss (reproduced here
on purpose)**: `label_place`'s `is_home` floor (`_HOME_NIGHT_SHARE_MIN = 0.3`,
`nora/domain/mobility.py`) cannot be met by ANY realistic work-from-home
pattern without also admitting the genuinely-ambiguous "substantial dwell in
both windows" case — because `night_share`'s denominator (`total_dwell`, all
hours) grows with every hour of honest daytime presence at the same cell,
`night_share` FALLS as a real work-from-home subject's day gets more honestly
represented, not as her home-ness falls. Computed against this fixture
(`night_share` = total night-window dwell / total dwell across every closed
`Stay` in the cluster, exactly as `label_place` computes it):

    synthetic_wfh_b       night_share = 0.1818   (40h night / 220h total)
    synthetic_ambiguous_e night_share = 0.2353   (20h night /  85h total)

Both are below the 0.3 floor (neither becomes `home`), and `synthetic_wfh_b`'s
share is LOWER than `synthetic_ambiguous_e`'s by a 0.0535 margin: the
work-from-home case's honest daytime dwell dilutes her `night_share` more than
the ambiguous case's narrower, more night-concentrated pattern does.
Reproduced here via two DIFFERENT stay-span shapes, not by hand-tuning one
threshold: `synthetic_wfh_b` sits 22h/day (00:00-22:00, four hours of night
PLUS a long daytime tail); `synthetic_ambiguous_e` sits a narrower 17h/day
(01:00-18:00, the same four hours of night against a shorter daytime tail) —
this is exactly the trade-off `nora/domain/mobility.py`'s `label_place`
docstring describes: no single window width separates the two, so the fixture
keeps both patterns distinct.

Columns match the `presence_fixes` row shape: person_id, ts (ms), lat, lng,
accuracy_m, wire_state, recorded_at (ms).
"""

from __future__ import annotations

import random
from datetime import date, datetime, timedelta
from zoneinfo import ZoneInfo

_HKT = ZoneInfo("Asia/Hong_Kong")

Row = tuple[str, int, float, float, float, str, int]

# A single shared "away" point, ~50km from every synthetic site used below
# -- far enough that a fix there always breaks `segment_stays`' 120m
# radius test against whichever site's group it follows. Used only to
# force each day's dwell session to close as its OWN `Stay` (see
# `_dwell_track`'s docstring for why this is needed at all).
_AWAY_LAT, _AWAY_LNG = 22.010, 113.550


def _local_ms(day: date, hour: float) -> int:
    """Epoch ms for `hour` local-HKT hours into `day`. `hour` may exceed 24
    to express a session crossing local midnight (e.g. hour_end=31 means
    07:00 the calendar day AFTER `day`) -- built via `zoneinfo`, matching
    `label_place`'s own local-clock windows, never naive UTC-offset math."""
    dt = datetime(day.year, day.month, day.day, tzinfo=_HKT) + timedelta(hours=hour)
    return int(dt.timestamp() * 1000)


def _jitter(rng: random.Random, meters: float = 15.0) -> tuple[float, float]:
    """A small seeded lat/lng offset so fixes are not suspiciously perfect
    grid points -- well inside `segment_stays`' 120m radius test. The flat
    degrees-per-meter conversion below is a local approximation valid at
    this fixture's small jitter scale and Hong Kong's ~22.3 deg latitude;
    it is not meant to generalize."""
    d_lat = (rng.random() * 2 - 1) * meters / 111_320.0
    d_lng = (rng.random() * 2 - 1) * meters / 102_000.0
    return d_lat, d_lng


def _dwell_track(
    person_id: str,
    *,
    start: date,
    n_days: int,
    hour_start: float,
    hour_end: float,
    lat: float,
    lng: float,
    seed: int,
    fix_interval_minutes: int = 30,
    accuracy_m: float = 50.0,
    day_step: int = 1,
) -> list[Row]:
    """One dwell session per day at (`lat`, `lng`), spanning local-HKT
    [`hour_start`, `hour_end`], `n_days` sessions `day_step` calendar days
    apart, fixes `fix_interval_minutes` apart within each session.

    A single fix at `_AWAY_LAT`/`_AWAY_LNG` is appended right after every
    session, including the last. Without it, two same-location sessions
    with NOTHING recorded between them (e.g. the 15h overnight gap between
    one day's 18:00 knock-off and the next day's 09:00 start) still
    satisfy `segment_stays`' radius test across that whole gap --
    `segment_stays` only ever breaks a group on DISTANCE, never on
    elapsed time -- and would silently bridge what should be two separate
    daily `Stay`s into one long multi-day `Stay`. That matters here
    specifically: a bridged `Stay`'s `ended_ts - started_ts` span covers
    the quiet overnight hours too, inflating `total_dwell` with time
    nobody was actually observed there and skewing `night_share`/
    `work_share` away from the exact values this fixture is built to hit.
    The away fix's own one-fix group always has zero span
    (`group[-1].ts - group[0].ts == 0`, per `Stay`'s own invariant), so it
    never itself reaches `min_dwell_ms` and `_close` drops it; if it
    survives as a trailing `open_stay` instead, `cluster_places`'
    `min_samples` gate drops it there as noise (it never shares a location
    with two or more other stays). Either way it contributes nothing to
    any real cluster -- it exists purely to break stay segmentation at the
    right point.
    """
    rng = random.Random(seed)
    rows: list[Row] = []
    n_fixes = round((hour_end - hour_start) * 60 / fix_interval_minutes) + 1
    for day_idx in range(n_days):
        day = start + timedelta(days=day_idx * day_step)
        for i in range(n_fixes):
            hour = hour_start + i * fix_interval_minutes / 60
            ts = _local_ms(day, hour)
            d_lat, d_lng = _jitter(rng)
            rows.append((
                person_id, ts, round(lat + d_lat, 6), round(lng + d_lng, 6),
                accuracy_m, "live", ts + 3_000,
            ))
        away_ts = _local_ms(day, hour_end + 1.0)
        rows.append((
            person_id, away_ts, _AWAY_LAT, _AWAY_LNG, accuracy_m, "live",
            away_ts + 3_000,
        ))
    return rows


# --- Scenario 1: clean office worker, zero night dwell -> `work` ----------
_WORKER_A_ROWS = _dwell_track(
    "synthetic_worker_a", start=date(2026, 8, 3), n_days=5,
    hour_start=9, hour_end=18, lat=22.301, lng=114.155, seed=1,
)

# --- Scenario 2: works from where she sleeps -> the near-miss `xfail` -----
_WFH_B_ROWS = _dwell_track(
    "synthetic_wfh_b", start=date(2026, 8, 3), n_days=6,
    hour_start=0, hour_end=22, lat=22.370, lng=114.110, seed=2,
)

# --- Scenario 3: the fail-closed proof case -> `unlabeled` ----------------
_AMBIGUOUS_E_ROWS = _dwell_track(
    "synthetic_ambiguous_e", start=date(2026, 8, 3), n_days=5,
    hour_start=1, hour_end=18, lat=22.420, lng=114.020, seed=3,
)

# --- Scenario 4: real home, no qualifying work place -----------------------
_HOME_ONLY_C_NIGHTS = _dwell_track(
    "synthetic_home_only_c", start=date(2026, 8, 3), n_days=8,
    hour_start=22, hour_end=31, lat=22.410, lng=113.960, seed=4,
)
# A minor secondary location: 3 brief weekday-morning visits, 1h each (3h
# total) -- clears `cluster_places`' min_samples (3 stays) but never
# `_MIN_WORK_DWELL_MS` (8h): a spurious cluster that must not become `work`.
_HOME_ONLY_C_QUASI_WORK = _dwell_track(
    "synthetic_home_only_c", start=date(2026, 8, 5), n_days=3,
    hour_start=9, hour_end=10, lat=22.250, lng=114.220, seed=5,
)

# --- Scenario 5: one desk, two identities across a simulated rename -------
_RENAMED_BEFORE_ROWS = _dwell_track(
    "synthetic_renamed_before", start=date(2026, 8, 3), n_days=2,
    hour_start=9, hour_end=18, lat=22.336, lng=114.190, seed=6,
)
_RENAMED_AFTER_ROWS = _dwell_track(
    "synthetic_renamed_after", start=date(2026, 8, 5), n_days=2,
    hour_start=9, hour_end=18, lat=22.336, lng=114.190, seed=7,
)

# --- Scenario 6: the accuracy_m <= 100 gate ---------------------------------
# One reading ~100m off synthetic_worker_a's true office centroid,
# timestamped inside her first (3 Aug 2026) work session, accuracy_m=110 --
# the row the gate exists to drop. Pinned as a literal: including it
# measurably shifts that session's Stay centroid and inflates its radius
# (proven in `test_reverting_the_accuracy_gate_would_change_the_result` below).
_ACCURACY_GATE_ROW: Row = (
    "synthetic_worker_a", 1_785_724_230_000, 22.301898, 114.155, 110.0,
    "live", 1_785_724_233_000,
)

CORPUS_ROWS: tuple[Row, ...] = tuple(sorted(
    [
        *_WORKER_A_ROWS,
        *_WFH_B_ROWS,
        *_AMBIGUOUS_E_ROWS,
        *_HOME_ONLY_C_NIGHTS,
        *_HOME_ONLY_C_QUASI_WORK,
        *_RENAMED_BEFORE_ROWS,
        *_RENAMED_AFTER_ROWS,
    ],
    key=lambda r: (r[0], r[1]),
))

# The row(s) an accuracy_m <= 100 gate would exclude: the one purpose-built
# row above, which is all `test_reverting_the_accuracy_gate_would_change_
# the_result` needs to prove the gate does real work.
CORPUS_ROWS_UNFILTERED: tuple[Row, ...] = (_ACCURACY_GATE_ROW,)
